// rr_arbiter.v
// Round-robin arbiter for N requesters (default 4).
// Implements interface_spec.md (rr_arbiter) as planned in microarchitecture.md.
//  - grant is one-hot or zero, only to a requester, work conserving, and a
//    combinational function of req and the priority pointer.
//  - The winner is the first requester with req high at or after ptr,
//    searching upwards and wrapping from N-1 to 0 (explicit compare with
//    LAST, so N need not be a power of two).
//  - On a rising edge with a grant, ptr moves to one past the winner; with no
//    request ptr holds. Reset (rst_n, active low, synchronous) sets ptr to 0.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer  PW      = $clog2(N);
    localparam [31:0]   LAST_32 = N - 1;
    localparam [31:0]   ONE_32  = 1;
    localparam [PW-1:0] LAST    = LAST_32[PW-1:0];
    localparam [PW-1:0] ONE     = ONE_32[PW-1:0];
    localparam [N-1:0]  BIT0    = {{(N-1){1'b0}}, 1'b1};

    reg [PW-1:0] ptr;
    reg [PW-1:0] ptr_next;
    reg [PW-1:0] winner;
    reg          granted;
    reg [PW-1:0] idx;
    reg [N-1:0]  sel;
    integer      k;

    // Wrapping priority search from ptr. Every output has a default first.
    always @* begin
        grant   = {N{1'b0}};
        winner  = ptr;
        granted = 1'b0;
        idx     = ptr;
        sel     = {N{1'b0}};
        for (k = 0; k < N; k = k + 1) begin
            sel = BIT0 << idx;
            if (!granted && ((req & sel) != {N{1'b0}})) begin
                grant   = sel;
                winner  = idx;
                granted = 1'b1;
            end
            if (idx == LAST) begin
                idx = {PW{1'b0}};
            end else begin
                idx = idx + ONE;
            end
        end
    end

    // Pointer update: one past the winner on a grant, hold otherwise.
    always @* begin
        ptr_next = ptr;
        if (granted) begin
            if (winner == LAST) begin
                ptr_next = {PW{1'b0}};
            end else begin
                ptr_next = winner + ONE;
            end
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else begin
            ptr <= ptr_next;
        end
    end

`ifdef FORMAL
    // Design-intent properties (read with `read -formal`).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    // Distance from p_a up to p_b, wrapping at N.
    function integer f_dist;
        input integer p_a;
        input integer p_b;
        begin
            f_dist = (p_b >= p_a) ? (p_b - p_a) : (p_b + N - p_a);
        end
    endfunction

    always @(*) begin
        if (f_past_valid) begin
            assert (ptr <= LAST);
            assert ((grant & (grant - BIT0)) == {N{1'b0}});
            assert ((grant & ~req) == {N{1'b0}});
            if (req != {N{1'b0}}) assert (grant != {N{1'b0}});
            assert (granted == (grant != {N{1'b0}}));
            if (granted) assert (grant == (BIT0 << winner));
        end
        cover (rst_n && (req == {N{1'b1}}));
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (ptr == {PW{1'b0}});
            end else if ($past(granted)) begin
                if ($past(winner) == LAST) assert (ptr == {PW{1'b0}});
                else                       assert (ptr == $past(winner) + ONE);
            end else begin
                assert (ptr == $past(ptr));
            end
            cover ($past(rst_n) && $past(granted) && ($past(winner) == LAST));
        end
    end

    genvar f_i;
    generate
        for (f_i = 0; f_i < N; f_i = f_i + 1) begin : g_formal
            reg [31:0] f_wait;
            initial f_wait = 32'd0;
            always @(posedge clk) begin
                if (!rst_n) f_wait <= 32'd0;
                else if (req[f_i] && !grant[f_i]) f_wait <= f_wait + 32'd1;
                else f_wait <= 32'd0;
            end
            always @(*) begin
                if (f_past_valid) begin
                    if (granted && req[f_i])
                        assert (f_dist(ptr, winner) <= f_dist(ptr, f_i));
                    assert (f_wait <= N - 1);
                    if (f_wait != 32'd0)
                        assert (f_wait + f_dist(ptr, f_i) <= N - 1);
                end
                cover (grant[f_i]);
            end
        end
    endgenerate
`endif

endmodule
