// rr_arbiter_tb.v
// Self-checking testbench for rr_arbiter: N=4 and N=5 side by side, each
// checked every cycle against a reference pointer model, with per-requester
// wait counters (fairness) and coverage counters that fail the run if a case
// from interface_spec.md section 6 was not reached.
module rr_arbiter_tb;
    reg        clk;
    reg        rst_n;
    reg  [3:0] req4;
    reg  [4:0] req5;
    wire [3:0] grant4;
    wire [4:0] grant5;

    rr_arbiter #(.N(4)) u_arb4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
    rr_arbiter #(.N(5)) u_arb5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));

    integer        passed;
    integer        failed;
    integer        cycle;
    integer        rot_k;
    reg            rot_mode;
    reg [31:0]     lfsr;
    reg [8*64-1:0] nonce;
    integer        t;
    integer        ti;
    integer        tj;
    integer        tx;

    integer   mptr      [0:1];
    integer   exp_w     [0:1];
    reg [7:0] r_s       [0:1];
    reg [7:0] g_s       [0:1];
    reg [7:0] prev_r    [0:1];
    integer   wait_cnt  [0:15];
    integer   cov_alone [0:15];
    integer   cov_none  [0:1];
    integer   cov_all   [0:1];
    integer   cov_maxw  [0:1];
    integer   cov_held  [0:1];
    integer   cov_rstt  [0:1];
    integer   cov_wrap  [0:1];

    initial clk = 1'b0;
    always #5 clk = ~clk;

    function integer lane_n;
        input integer lane;
        begin
            lane_n = (lane == 0) ? 4 : 5;
        end
    endfunction

    // Reference: first requester with req high at or after p, wrapping at n.
    function integer rr_pick;
        input [7:0]   r;
        input integer n;
        input integer p;
        integer k;
        integer idx;
        begin
            rr_pick = -1;
            for (k = 0; k < n; k = k + 1) begin
                idx = (p + k) % n;
                if (rr_pick < 0 && (((r >> idx) & 8'd1) != 8'd0)) rr_pick = idx;
            end
        end
    endfunction

    task check;
        input            cond;
        input integer    lane;
        input [8*64-1:0] what;
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("rr_arbiter_tb: N=%0d cycle %0d: %0s", lane_n(lane), cycle, what);
            end
        end
    endtask

    task next_rand;
        integer s;
        begin
            for (s = 0; s < 7; s = s + 1)
                lfsr = {lfsr[30:0], lfsr[31] ^ lfsr[21] ^ lfsr[1] ^ lfsr[0]};
        end
    endtask

    // Check one lane's outputs for the current (settled) inputs.
    task eval_lane;
        input integer lane;
        integer   n;
        integer   w;
        integer   i;
        integer   ix;
        reg [7:0] r;
        reg [7:0] g;
        reg [7:0] e;
        reg [7:0] pr;
        begin
            n  = lane_n(lane);
            r  = (lane == 0) ? {4'b0000, req4}   : {3'b000, req5};
            g  = (lane == 0) ? {4'b0000, grant4} : {3'b000, grant5};
            pr = prev_r[lane[0]];
            w  = rr_pick(r, n, mptr[lane[0]]);
            e  = (w < 0) ? 8'd0 : (8'd1 << w);
            check(g == e, lane, "grant differs from reference pointer model");
            if (rot_mode)
                check(w == (rot_k % n), lane, "strict rotation with all requesting after reset");
            for (i = 0; i < n; i = i + 1) begin
                ix = lane * 8 + i;
                if (((r >> i) & 8'd1) != 8'd0) begin
                    if (((g >> i) & 8'd1) != 8'd0) begin
                        if (wait_cnt[ix[3:0]] == n - 1)
                            cov_maxw[lane[0]] = cov_maxw[lane[0]] + 1;
                    end else begin
                        check(wait_cnt[ix[3:0]] < n - 1, lane,
                              "held request waited N-1 cycles and is still not granted");
                    end
                    if ((((pr >> i) & 8'd1) != 8'd0) && (wait_cnt[ix[3:0]] > 0) &&
                        (((r ^ pr) & ~(8'd1 << i)) != 8'd0))
                        cov_held[lane[0]] = cov_held[lane[0]] + 1;
                end
                if ((r == (8'd1 << i)) && (g == r))
                    cov_alone[ix[3:0]] = cov_alone[ix[3:0]] + 1;
            end
            if (r == 8'd0) cov_none[lane[0]] = cov_none[lane[0]] + 1;
            if (r == ((8'd1 << n) - 8'd1)) cov_all[lane[0]] = cov_all[lane[0]] + 1;
            if (!rst_n && (r != 8'd0)) cov_rstt[lane[0]] = cov_rstt[lane[0]] + 1;
            if (rst_n && (w == n - 1)) cov_wrap[lane[0]] = cov_wrap[lane[0]] + 1;
            exp_w[lane[0]]  = w;
            r_s[lane[0]]    = r;
            g_s[lane[0]]    = g;
            prev_r[lane[0]] = r;
        end
    endtask

    // Advance one lane's model across the rising edge, from sampled values.
    task advance_lane;
        input integer lane;
        integer   n;
        integer   w;
        integer   i;
        integer   ix;
        reg [7:0] r;
        reg [7:0] g;
        begin
            n = lane_n(lane);
            w = exp_w[lane[0]];
            r = r_s[lane[0]];
            g = g_s[lane[0]];
            if (!rst_n) mptr[lane[0]] = 0;
            else if (w >= 0) mptr[lane[0]] = (w + 1) % n;
            for (i = 0; i < n; i = i + 1) begin
                ix = lane * 8 + i;
                if (rst_n && (((r >> i) & 8'd1) != 8'd0) && (((g >> i) & 8'd1) == 8'd0))
                    wait_cnt[ix[3:0]] = wait_cnt[ix[3:0]] + 1;
                else
                    wait_cnt[ix[3:0]] = 0;
            end
        end
    endtask

    // One clock cycle: drive at the falling edge, check, then cross the edge.
    task cyc;
        input [3:0] r4;
        input [4:0] r5;
        input       rst;
        begin
            @(negedge clk);
            req4  = r4;
            req5  = r5;
            rst_n = rst;
            #1;
            eval_lane(0);
            eval_lane(1);
            @(posedge clk);
            advance_lane(0);
            advance_lane(1);
            if (rot_mode) rot_k = rot_k + 1;
            cycle = cycle + 1;
        end
    endtask

    initial begin
        passed   = 0;
        failed   = 0;
        cycle    = 0;
        rot_k    = 0;
        rot_mode = 1'b0;
        lfsr     = 32'h1F2E3D4C;
        rst_n    = 1'b0;
        req4     = 4'h0;
        req5     = 5'h00;
        for (ti = 0; ti < 16; ti = ti + 1) begin
            wait_cnt[ti[3:0]]  = 0;
            cov_alone[ti[3:0]] = 0;
        end
        for (ti = 0; ti < 2; ti = ti + 1) begin
            mptr[ti[0]]     = 0;
            exp_w[ti[0]]    = -1;
            r_s[ti[0]]      = 8'd0;
            g_s[ti[0]]      = 8'd0;
            prev_r[ti[0]]   = 8'd0;
            cov_none[ti[0]] = 0;
            cov_all[ti[0]]  = 0;
            cov_maxw[ti[0]] = 0;
            cov_held[ti[0]] = 0;
            cov_rstt[ti[0]] = 0;
            cov_wrap[ti[0]] = 0;
        end
        nonce = "unset";
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = "unset";

        // Reset with no traffic.
        for (t = 0; t < 3; t = t + 1) cyc(4'h0, 5'h00, 1'b0);

        // Everyone requesting right after reset: strict rotation, N-1 waits, wrap.
        rot_mode = 1'b1;
        rot_k    = 0;
        for (t = 0; t < 15; t = t + 1) cyc(4'hF, 5'h1F, 1'b1);
        rot_mode = 1'b0;

        // No requests.
        for (t = 0; t < 3; t = t + 1) cyc(4'h0, 5'h00, 1'b1);

        // Each requester alone.
        for (t = 0; t < 5; t = t + 1) begin
            cyc(4'b0001 << t, 5'b00001 << t, 1'b1);
            cyc(4'b0001 << t, 5'b00001 << t, 1'b1);
        end

        // A held request (requester 2) among changing others.
        for (t = 0; t < 40; t = t + 1) begin
            next_rand;
            cyc(lfsr[3:0] | 4'b0100, lfsr[12:8] | 5'b00100, 1'b1);
        end

        // Random subsets, dense and sparse; requests dropped and raised.
        for (t = 0; t < 300; t = t + 1) begin
            next_rand;
            if (lfsr[31]) cyc(lfsr[3:0] | lfsr[7:4], lfsr[12:8] | lfsr[17:13], 1'b1);
            else          cyc(lfsr[3:0] & lfsr[7:4], lfsr[12:8] & lfsr[17:13], 1'b1);
        end

        // Reset during traffic, then rotation from pointer 0 again.
        for (t = 0; t < 10; t = t + 1) begin
            next_rand;
            cyc(lfsr[3:0] | lfsr[7:4], lfsr[12:8] | lfsr[17:13], 1'b1);
        end
        for (t = 0; t < 2; t = t + 1) begin
            next_rand;
            cyc(lfsr[3:0] | 4'b1000, lfsr[12:8] | 5'b10000, 1'b0);
        end
        rot_mode = 1'b1;
        rot_k    = 0;
        for (t = 0; t < 10; t = t + 1) cyc(4'hF, 5'h1F, 1'b1);
        rot_mode = 1'b0;

        // Random traffic with periodic reset.
        for (t = 0; t < 120; t = t + 1) begin
            next_rand;
            cyc(lfsr[3:0] | lfsr[7:4], lfsr[12:8] ^ lfsr[17:13], (t % 29) != 28);
        end

        cyc(4'h0, 5'h00, 1'b1);

        // Coverage goals: each must have been reached.
        for (ti = 0; ti < 2; ti = ti + 1) begin
            check(cov_none[ti[0]] > 0, ti, "coverage: no-request cycle");
            check(cov_all[ti[0]]  > 0, ti, "coverage: everyone requesting");
            check(cov_maxw[ti[0]] > 0, ti, "coverage: longest fair wait (N-1)");
            check(cov_held[ti[0]] > 0, ti, "coverage: held request among changing others");
            check(cov_rstt[ti[0]] > 0, ti, "coverage: reset during traffic");
            check(cov_wrap[ti[0]] > 0, ti, "coverage: pointer wrap from N-1 to 0");
            for (tj = 0; tj < lane_n(ti); tj = tj + 1) begin
                tx = ti * 8 + tj;
                check(cov_alone[tx[3:0]] > 0, ti, "coverage: requester alone");
            end
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
